export type Recipient = Readonly<{
  name: string;
  postalAddress: string;
}>;

export type ProviderRequest = Readonly<{
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}>;

export type ShippingDependencies = Readonly<{
  repository: Readonly<{
    get: (shipmentId: string) => Promise<unknown>;
    save: (shipmentId: string, record: unknown) => Promise<void>;
  }>;
  atlas: Readonly<{
    book: (request: ProviderRequest) => Promise<unknown>;
  }>;
  beacon: Readonly<{
    reserve: (request: ProviderRequest) => Promise<unknown>;
  }>;
  logger: Readonly<{
    info: (event: Record<string, unknown>) => void;
  }>;
}>;

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type Classification = "unknown_failure" | "invalid_provider_response" | "repository_failure";
type FailedAt = Provider | "repository";

type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

type ShipmentFields = Readonly<{
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type QueuedShipment = ShipmentFields & Readonly<{
  state: "queued";
}>;

type DispatchedShipment = ShipmentFields & Readonly<{
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}>;

type DeferredShipment = ShipmentFields & Readonly<{
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: readonly Rejection[];
}>;

type UnavailableShipment = ShipmentFields & Readonly<{
  state: "unavailable";
  rejections: readonly Rejection[];
}>;

type StoredShipment = QueuedShipment | DispatchedShipment | DeferredShipment | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type InvalidCommandBody = Readonly<{ code: "invalid_command" }>;
type NotFoundBody = Readonly<{ code: "not_found" }>;
type AbortBody = Readonly<{
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: FailedAt;
  classification: Classification;
  rejections: readonly Rejection[];
}>;

export type ServiceResponse = Readonly<{
  status: number;
  body: PublicShipment | InvalidCommandBody | NotFoundBody | AbortBody;
}>;

type Command =
  | Readonly<{ op: "get"; shipmentId: string }>
  | Readonly<{ op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient }>;

type ProviderOutcome =
  | Readonly<{ kind: "confirmed"; bookingId: string }>
  | Readonly<{ kind: "refused"; reason: RefusalReason }>
  | Readonly<{ kind: "throttled"; retryAtMs: number }>
  | Readonly<{ kind: "aborted"; classification: Exclude<Classification, "repository_failure"> }>;

type DispatchContext = Readonly<{
  shipment: QueuedShipment | DeferredShipment;
  command: Extract<Command, { op: "dispatch" }>;
  rejections: readonly Rejection[];
}>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isNonemptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isNonblankString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function isSafeNonnegativeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

function isPositiveSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || !isNonemptyString(value.shipmentId)) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    !isSafeNonnegativeInteger(value.nowMs) ||
    !isObject(value.recipient) ||
    !isNonblankString(value.recipient.name) ||
    !isNonblankString(value.recipient.postalAddress)
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function parseRejections(value: unknown): readonly Rejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }
  const rejections: Rejection[] = [];
  for (const item of value) {
    if (!isObject(item) || !isProvider(item.provider) || !isRefusalReason(item.reason)) {
      return undefined;
    }
    rejections.push({ provider: item.provider, reason: item.reason });
  }
  return rejections;
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    !isNonemptyString(value.id) ||
    !isNonemptyString(value.routeCode) ||
    !isPositiveSafeInteger(value.parcelGrams)
  ) {
    return undefined;
  }
  const fields = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  } as const;

  if (value.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    isNonemptyString(value.bookingId) &&
    isSafeNonnegativeInteger(value.dispatchedAtMs)
  ) {
    return {
      ...fields,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  const rejections = parseRejections(value.rejections);
  if (value.state === "deferred" && isProvider(value.nextProvider) && isSafeNonnegativeInteger(value.retryAtMs) && rejections) {
    return {
      ...fields,
      state: "deferred",
      nextProvider: value.nextProvider,
      retryAtMs: value.retryAtMs,
      rejections,
    };
  }
  if (value.state === "unavailable" && rejections) {
    return {
      ...fields,
      state: "unavailable",
      rejections,
    };
  }
  return undefined;
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: shipment.rejections,
      };
    case "unavailable":
      return {
        ...fields,
        state: "unavailable",
        rejections: shipment.rejections,
      };
  }
}

function abortBody(
  shipmentId: string,
  failedAt: FailedAt,
  classification: Classification,
  rejections: readonly Rejection[],
): AbortBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections,
  };
}

function emitAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: FailedAt,
  classification: Classification,
  rejections: readonly Rejection[],
): ServiceResponse {
  dependencies.logger.info({
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections,
  });
  return {
    status: 500,
    body: abortBody(shipmentId, failedAt, classification, rejections),
  };
}

function buildRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function classifyAtlasRejection(value: unknown, nowMs: number): ProviderOutcome {
  if (!isObject(value)) {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (value.code === "cannot_ship") {
    if (isRefusalReason(value.reason)) {
      return { kind: "refused", reason: value.reason };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (value.code === "rate_limited") {
    if (typeof value.retryAtMs === "number" && Number.isSafeInteger(value.retryAtMs) && value.retryAtMs > nowMs) {
      return { kind: "throttled", retryAtMs: value.retryAtMs };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function classifyBeaconRejection(value: unknown, nowMs: number): ProviderOutcome {
  if (!isObject(value)) {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (value.type === "rejected") {
    if (isObject(value.details) && isRefusalReason(value.details.reason)) {
      return { kind: "refused", reason: value.details.reason };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (value.type === "throttled") {
    if (
      isObject(value.details) &&
      typeof value.details.retryAtMs === "number" &&
      Number.isSafeInteger(value.details.retryAtMs) &&
      value.details.retryAtMs > nowMs
    ) {
      return { kind: "throttled", retryAtMs: value.details.retryAtMs };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function classifyConfirmation(provider: Provider, value: unknown): ProviderOutcome {
  if (!isObject(value)) {
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (provider === "atlas" && isNonemptyString(value.bookingId)) {
    return { kind: "confirmed", bookingId: value.bookingId };
  }
  if (provider === "beacon" && isNonemptyString(value.reference)) {
    return { kind: "confirmed", bookingId: value.reference };
  }
  return { kind: "aborted", classification: "invalid_provider_response" };
}

async function attemptProvider(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<ProviderOutcome> {
  try {
    const confirmation = provider === "atlas"
      ? await dependencies.atlas.book(request)
      : await dependencies.beacon.reserve(request);
    return classifyConfirmation(provider, confirmation);
  } catch (error) {
    return provider === "atlas"
      ? classifyAtlasRejection(error, nowMs)
      : classifyBeaconRejection(error, nowMs);
  }
}

async function saveDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  decision: StoredShipment,
  event: Record<string, unknown>,
  status: number,
  rejections: readonly Rejection[],
): Promise<ServiceResponse> {
  try {
    await dependencies.repository.save(shipment.id, decision);
  } catch {
    return emitAbort(dependencies, shipment.id, "repository", "repository_failure", rejections);
  }
  dependencies.logger.info(event);
  return { status, body: publicShipment(decision) };
}

function hasRefusal(rejections: readonly Rejection[], provider: Provider): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

async function dispatchFromProvider(
  dependencies: ShippingDependencies,
  context: DispatchContext,
  provider: Provider,
): Promise<ServiceResponse> {
  if (hasRefusal(context.rejections, provider)) {
    return emitAbort(dependencies, context.shipment.id, provider, "invalid_provider_response", context.rejections);
  }

  const request = buildRequest(context.shipment, context.command.recipient);
  const outcome = await attemptProvider(dependencies, provider, request, context.command.nowMs);

  switch (outcome.kind) {
    case "confirmed": {
      const dispatched: DispatchedShipment = {
        schemaVersion: 1,
        id: context.shipment.id,
        routeCode: context.shipment.routeCode,
        parcelGrams: context.shipment.parcelGrams,
        state: "dispatched",
        provider,
        bookingId: outcome.bookingId,
        dispatchedAtMs: context.command.nowMs,
      };
      return saveDecision(
        dependencies,
        context.shipment,
        dispatched,
        { shipmentId: context.shipment.id, action: "dispatched", provider },
        200,
        context.rejections,
      );
    }
    case "throttled": {
      const deferred: DeferredShipment = {
        schemaVersion: 1,
        id: context.shipment.id,
        routeCode: context.shipment.routeCode,
        parcelGrams: context.shipment.parcelGrams,
        state: "deferred",
        nextProvider: provider,
        retryAtMs: outcome.retryAtMs,
        rejections: context.rejections,
      };
      return saveDecision(
        dependencies,
        context.shipment,
        deferred,
        {
          shipmentId: context.shipment.id,
          action: "deferred",
          provider,
          retryAtMs: outcome.retryAtMs,
          rejections: context.rejections,
        },
        202,
        context.rejections,
      );
    }
    case "refused": {
      const rejections = [...context.rejections, { provider, reason: outcome.reason }] as const;
      if (provider === "atlas") {
        return dispatchFromProvider(dependencies, { ...context, rejections }, "beacon");
      }
      const unavailable: UnavailableShipment = {
        schemaVersion: 1,
        id: context.shipment.id,
        routeCode: context.shipment.routeCode,
        parcelGrams: context.shipment.parcelGrams,
        state: "unavailable",
        rejections,
      };
      return saveDecision(
        dependencies,
        context.shipment,
        unavailable,
        { shipmentId: context.shipment.id, action: "unavailable", rejections },
        422,
        rejections,
      );
    }
    case "aborted":
      return emitAbort(dependencies, context.shipment.id, provider, outcome.classification, context.rejections);
  }
}

function businessResponseForTerminal(shipment: DispatchedShipment | DeferredShipment | UnavailableShipment): ServiceResponse {
  if (shipment.state === "dispatched") {
    return { status: 200, body: publicShipment(shipment) };
  }
  if (shipment.state === "deferred") {
    return { status: 202, body: publicShipment(shipment) };
  }
  return { status: 422, body: publicShipment(shipment) };
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      return emitAbort(dependencies, command.shipmentId, "repository", "repository_failure", []);
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (!shipment) {
      return emitAbort(dependencies, command.shipmentId, "repository", "repository_failure", []);
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }

    if (shipment.state === "dispatched" || shipment.state === "unavailable") {
      return businessResponseForTerminal(shipment);
    }
    if (shipment.state === "deferred") {
      if (command.nowMs < shipment.retryAtMs) {
        return businessResponseForTerminal(shipment);
      }
      return dispatchFromProvider(
        dependencies,
        { shipment, command, rejections: shipment.rejections },
        shipment.nextProvider,
      );
    }

    return dispatchFromProvider(dependencies, { shipment, command, rejections: [] }, "atlas");
  }

  return { handle };
}
